/** unicode.Is(table, r) for a table above. */
export function inTable(table, r) {
  let lo = 0, hi = (table.length >> 1) - 1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    if (r < table[2 * mid]) hi = mid - 1;
    else if (r > table[2 * mid + 1]) lo = mid + 1;
    else return true;
  }
  return false;
}

/** unicode.IsSymbol */
export const isSymbol = (r) => inTable(Sm, r) || inTable(Sc, r) || inTable(Sk, r) || inTable(So, r);

/** unicode.IsPunct */
export const isPunct = (r) => inTable(P, r);
